"""Offline WebGL line preview. No external scripts or geometry services."""
MODEL_HTML=r'''<div class="actions"><button type="button" class="secondary" id="model-open" onclick="loadModelPreview()" disabled>3D-Druckwegvorschau laden · Prototyp</button><button type="button" class="quiet" id="model-cancel" onclick="resetModelPreview('3D-Laden abgebrochen.')" hidden>Laden abbrechen</button></div><p id="model-status" class="muted small" role="status"></p><div id="model-view" hidden><canvas id="model-canvas" tabindex="0" aria-label="Interaktive 3D-Druckwegvorschau; Pfeiltasten drehen, Plus und Minus zoomen"></canvas><div class="actions"><button type="button" class="quiet" onclick="modelViewer?.zoom(1.25)">Vergrößern +</button><button type="button" class="quiet" onclick="modelViewer?.zoom(.8)">Verkleinern −</button><button type="button" class="quiet" onclick="modelViewer?.reset()">Ansicht zurücksetzen</button></div><p class="muted small">Ziehen: drehen · Mausrad / zwei Finger: zoomen · Pfeiltasten / + / − ebenfalls möglich.</p><p id="model-warnings" class="muted small"></p></div><style>#model-canvas{display:block;width:100%;height:360px;background:#10171f;border:1px solid var(--line);border-radius:12px;touch-action:none;cursor:grab}#model-canvas:active{cursor:grabbing}@media(max-width:600px){ #model-canvas{height:280px}}</style>'''

MODEL_JS=r'''
let modelLoad=null,modelGeneration=0,modelPlate=null,modelViewer=null;
function resetModelPreview(message=''){if(modelLoad)cancelDetailLoad(modelLoad);modelLoad=null;modelGeneration++;modelPlate=null;modelViewer?.dispose();modelViewer=null;byId('model-view').hidden=true;byId('model-cancel').hidden=true;byId('model-status').textContent=message;byId('model-open').textContent='3D-Druckwegvorschau laden · Prototyp';byId('model-open').disabled=!detailReady;byId('start-review-button').disabled=startingPrint||!detailReady||!detailContext||!!detailFile?.blocked;}
function syncModelPlate(index){if(modelPlate!==null&&String(modelPlate)!==String(index))resetModelPreview();byId('model-open').disabled=!detailReady||!!modelLoad||!!modelViewer}
async function loadModelPreview(){if(!detailReady||startingPrint||modelLoad)return;resetModelPreview();invalidatePrintReview();const generation=detailGeneration,version=++modelGeneration,plate=Number(byId('detail-plate').value),load={file:detailFile.token,viewer:'3d-'+(globalThis.crypto?.randomUUID?.()||(Date.now()+'-'+Math.random())),complete:false,ticket:null};modelLoad=load;modelPlate=plate;byId('model-open').disabled=true;byId('model-cancel').hidden=false;byId('start-review-button').disabled=true;byId('model-status').textContent='3D-Datei wird im Hintergrund gelesen …';
try{let data=await storageJSON('/storage/model',{method:'POST',body:new URLSearchParams({file:load.file,plate,viewer:load.viewer,csrf_token:csrf})});load.ticket=data.ticket;if(version!==modelGeneration||generation!==detailGeneration){cancelDetailLoad(load);return}while(data.state==='loading'){byId('model-status').textContent=data.phase==='building'?'3D-Druckwege werden aufbereitet …':'3D-Datei wird gelesen: '+sizeLabel(data.received||0)+' / '+sizeLabel(data.total||detailFile.size);await new Promise(r=>setTimeout(r,800));if(version!==modelGeneration||generation!==detailGeneration)return;data=await storageJSON('/api/storage/details?ticket='+encodeURIComponent(load.ticket))}load.complete=true;if(version!==modelGeneration||generation!==detailGeneration)return;if(data.state!=='done'||!data.model)throw Error(data.error||'3D-Laden abgebrochen.');byId('model-view').hidden=false;modelViewer=createModelViewer(data.model);byId('model-warnings').textContent=data.model.warnings.join(' ');byId('model-status').textContent='Modellplatte '+plate+' · '+data.model.segments.toLocaleString('de-DE')+' dargestellte Druckwegsegmente · Prototyp';byId('model-open').textContent='3D-Druckwegvorschau geladen';}
catch(e){cancelDetailLoad(load);if(version===modelGeneration&&generation===detailGeneration){byId('model-status').textContent=e.message;byId('model-view').hidden=true}}
finally{if(version===modelGeneration&&generation===detailGeneration){modelLoad=null;byId('model-cancel').hidden=true;byId('model-open').disabled=!!modelViewer||!detailReady;byId('start-review-button').disabled=!detailReady||!detailContext||!!detailFile?.blocked}}
}
function createModelViewer(model){const canvas=byId('model-canvas'),gl=canvas.getContext('webgl',{alpha:false,antialias:true});if(!gl)throw Error('WebGL ist in diesem Browser nicht verfügbar. Das gespeicherte Vorschaubild bleibt nutzbar.');
const bytes=value=>Uint8Array.from(atob(value),c=>c.charCodeAt(0));const xyz=bytes(model.positions),rgb=bytes(model.colors);if(xyz.byteLength!==model.segments*24||rgb.length!==model.segments*6)throw Error('3D-Geometriedaten unvollständig.');
const shaders=[],buffers=[],controller=new AbortController();let program,disposed=false;
const dispose=()=>{disposed=true;controller.abort();observer?.disconnect();for(const buffer of buffers)gl.deleteBuffer(buffer);if(program)gl.deleteProgram(program);for(const shader of shaders)gl.deleteShader(shader)};let observer;
try{const shader=(kind,source)=>{const s=gl.createShader(kind);shaders.push(s);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error('3D-Darstellung wird von diesem Grafiktreiber nicht unterstützt.');return s};program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,'attribute vec3 p;attribute vec3 c;uniform vec3 center;uniform float extent;uniform vec2 angle;uniform float scale;uniform float aspect;varying vec3 color;void main(){vec3 q=(p-center)/extent;float x=cos(angle.x)*q.x-sin(angle.x)*q.y;float y=sin(angle.x)*q.x+cos(angle.x)*q.y;float z=sin(angle.y)*y+cos(angle.y)*q.z;gl_Position=vec4(x*scale/aspect,(cos(angle.y)*y-sin(angle.y)*q.z)*scale,z*.2,1.);color=c;}'));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,'precision mediump float;varying vec3 color;void main(){vec3 c=color;if(dot(c,vec3(.2126,.7152,.0722))<.06)c=max(c,vec3(.38));gl_FragColor=vec4(c,1.);}'));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error('3D-Grafik konnte nicht initialisiert werden.');gl.useProgram(program);
for(const [name,data,size,type,normalized] of [['p',new Float32Array(xyz.buffer),3,gl.FLOAT,false],['c',rgb,3,gl.UNSIGNED_BYTE,true]]){const buffer=gl.createBuffer();buffers.push(buffer);gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,data,gl.STATIC_DRAW);const a=gl.getAttribLocation(program,name);gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,size,type,normalized,0,0)}
const location=name=>gl.getUniformLocation(program,name),center=model.bounds[0].map((v,i)=>(v+model.bounds[1][i])/2),extent=Math.max(1,...model.bounds[0].map((v,i)=>model.bounds[1][i]-v));let yaw=-.6,pitch=-.9,zoom=1;const draw=()=>{if(disposed)return;const ratio=Math.min(devicePixelRatio||1,2),width=Math.max(1,Math.round(canvas.clientWidth*ratio)),height=Math.max(1,Math.round(canvas.clientHeight*ratio));if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height}gl.viewport(0,0,width,height);gl.clearColor(.063,.09,.12,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.enable(gl.DEPTH_TEST);gl.useProgram(program);gl.uniform3fv(location('center'),center);gl.uniform1f(location('extent'),extent);gl.uniform2f(location('angle'),yaw,pitch);gl.uniform1f(location('scale'),Math.min(1,width/height)*zoom);gl.uniform1f(location('aspect'),width/height);gl.drawArrays(gl.LINES,0,model.segments*2)};const zoomBy=f=>{zoom=Math.min(12,Math.max(.2,zoom*f));draw()},reset=()=>{yaw=-.6;pitch=-.9;zoom=1;draw()};const pointers=new Map(),distance=()=>{const p=[...pointers.values()];return p.length===2?Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y):0};let pinch=0;
canvas.addEventListener('pointerdown',e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});canvas.setPointerCapture(e.pointerId);pinch=distance()},{signal:controller.signal});canvas.addEventListener('pointermove',e=>{const old=pointers.get(e.pointerId);if(!old)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const next=distance();if(pinch>0)zoomBy(next/pinch);pinch=next}else{yaw+=(e.clientX-old.x)/150;pitch=Math.max(-1.5,Math.min(1.5,pitch+(e.clientY-old.y)/150));draw()}},{signal:controller.signal});for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,e=>{pointers.delete(e.pointerId);pinch=distance()},{signal:controller.signal});canvas.addEventListener('wheel',e=>{e.preventDefault();zoomBy(Math.exp(-e.deltaY*.001))},{passive:false,signal:controller.signal});canvas.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key))yaw+=e.key==='ArrowLeft'?-.1:.1;else if(['ArrowUp','ArrowDown'].includes(e.key))pitch=Math.max(-1.5,Math.min(1.5,pitch+(e.key==='ArrowUp'?-.1:.1)));else if(['+','='].includes(e.key))zoomBy(1.2);else if(e.key==='-')zoomBy(1/1.2);else if(e.key==='Home')reset();else return;e.preventDefault();draw()},{signal:controller.signal});observer=new ResizeObserver(draw);observer.observe(canvas);draw();return {zoom:zoomBy,reset,dispose};
}catch(e){dispose();throw e}
}
'''
